class TodoList:
    def __init__(self):
        self.todos = []
        self.next_id = 1

    def add(self, title):
        todo_id = self.next_id
        self.next_id += 1
        self.todos.append({'id': todo_id, 'title': title, 'done': False})
        return todo_id
    def done(self, item_id):
        for todo in self.todos:
            if todo['id'] == item_id:
                todo['done'] = True
                break

    def remove(self, item_id):
        for i, todo in enumerate(self.todos):
            if todo['id'] == item_id:
                del self.todos[i]
                return
        raise KeyError("Item with id {} not found".format(item_id))

    def pending(self):
        return [todo['title'] for todo in self.todos if not todo['done']]

